import{_ as e,o as a,c as n,a2 as t}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Questionnaire Answers","description":"How to answer the assessment questions no Azure API can answer, so CASA, DevOps Capability, FinOps, SMART, the AI workload review and the rest produce a complete score.","frontmatter":{"description":"How to answer the assessment questions no Azure API can answer, so CASA, DevOps Capability, FinOps, SMART, the AI workload review and the rest produce a complete score."},"headers":[],"relativePath":"assessment/questionnaire-answers.md","filePath":"assessment/questionnaire-answers.md"}'),i={name:"assessment/questionnaire-answers.md"};function o(r,s,l,d,h,p){return a(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="questionnaire-answers" tabindex="-1">Questionnaire Answers <a class="header-anchor" href="#questionnaire-answers" aria-label="Permalink to &quot;Questionnaire Answers&quot;">​</a></h1><p>Many assessments include questions that no Azure API can answer. &quot;Is the shared-responsibility model understood and documented?&quot; and &quot;Do you hold blameless post-incident reviews?&quot; are about how your organisation works, not about how a resource is configured. Scout calls these <strong>manual</strong> rules.</p><p>Until you answer them, manual rules show as <strong>Manual</strong> and are left out of the score. They are never counted as failures. Once answered, they are scored like any other check and marked <strong>Answered</strong>, so a reader can always tell a person&#39;s answer from Azure evidence.</p><p>Some assessments are mostly questions: CASA has 24 of 31, the AI workload review 32 of 34 and the FinOps Review 15 of 22. The <a href="./../reference/assessment-catalogue.html">Assessment Catalogue</a> lists the manual count for every assessment.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li><p><strong>Get the questions.</strong> Every assessment run writes <code>assessment-questions.csv</code> into its report folder, with one row per question. To get the file without running a scan:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Export-ScoutAssessmentQuestion</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Microsoft: CASA&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Microsoft: FinOps Review&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Path .\\answers.csv</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p><strong>Answer them.</strong> Open the CSV in Excel or any editor and fill in the <code>Answer</code> column. <code>Note</code>, <code>AnsweredBy</code> and <code>AnsweredAt</code> are optional. Leave a row blank to skip it.</p><p>You can also answer in the React report. In each assessment&#39;s <strong>Review and availability agenda</strong>, choose an answer next to each question, then select <strong>download answers</strong>. The report saves <code>assessment-answers.json</code>, and the report file itself is never changed.</p></li><li><p><strong>Run again with the answers.</strong> To re-score the collection you already have, without scanning Azure again:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Microsoft: CASA&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> \`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FromCollect C:\\AzureScout\\</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\assessment</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">report\\collect.json </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AssessmentAnswers .\\answers.csv</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Or pass <code>-AssessmentAnswers</code> on a normal scan.</p></li></ol><p>The wizard asks for the answer file after you choose assessments, but only when the chosen assessments have questions, and it says how many there are.</p><h2 id="answers" tabindex="-1">Answers <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;Answers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Write</th><th>Scored as</th></tr></thead><tbody><tr><td><code>Yes</code>, <code>Y</code>, <code>Pass</code>, <code>Met</code>, <code>Implemented</code>, <code>Done</code></td><td><strong>Met</strong> (Pass)</td></tr><tr><td><code>Partial</code>, <code>Partly</code>, <code>In progress</code>, <code>Some</code></td><td><strong>Partially met</strong> (Partial)</td></tr><tr><td><code>No</code>, <code>N</code>, <code>Fail</code>, <code>Not met</code>, <code>Not implemented</code></td><td><strong>Not met</strong> (Fail)</td></tr><tr><td><code>N/A</code>, <code>NA</code>, <code>Not applicable</code></td><td><strong>Not assessed</strong>, left out of the score, with your note kept</td></tr></tbody></table><p>Case doesn&#39;t matter. Scout reports any other word as a warning naming the question, and skips it rather than guessing.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li><strong>Answers only apply to manual questions.</strong> If Scout evaluates a rule from Azure data, an answer for that rule is ignored, because the data is the evidence.</li><li><strong>A question can be answered even when its data is missing.</strong> For example, SMART on an estate with no Azure Migrate project marks its data checks Unknown, but its organisational questions can still be answered and scored.</li><li><strong>Each run records what it used.</strong> <code>assessment-answers.json</code> in the report folder lists every answer applied. The new <code>assessment-questions.csv</code> comes back pre-filled with those answers, so each run&#39;s file is the starting point for the next.</li><li><strong>Multi-tenant runs use one file for every tenant.</strong> Question IDs are the same in every tenant. If the answers differ between tenants, run each tenant separately with its own file.</li><li><strong>Answers are visible everywhere results are.</strong> In <code>findings.json</code>, the Json report and the React report&#39;s CSV export, each finding carries <code>Source</code> (<code>Data</code>, <code>Answer</code> or <code>Unanswered</code>), plus <code>Answer</code>, <code>AnswerNote</code>, <code>AnsweredBy</code> and <code>AnsweredAt</code> when it was answered.</li></ul><h2 id="file-formats" tabindex="-1">File formats <a class="header-anchor" href="#file-formats" aria-label="Permalink to &quot;File formats&quot;">​</a></h2><p><strong>CSV.</strong> These are the columns Scout writes. Only <code>RuleId</code> and <code>Answer</code> are required, and other columns are ignored, so the exported file can be used unchanged.</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RuleId,Assessment,Framework,Area,Severity,Question,Guidance,Answer,Note,AnsweredBy,AnsweredAt</span></span>
<span class="line"><span>CASA-TR-01,Microsoft: CASA,CASA,...,low,&quot;The role of the cloud service provider ...&quot;,&quot;...&quot;,Yes,Documented in the cloud policy,Security team,2026-11-24</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>JSON.</strong> This is what the report&#39;s download button and each run write:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schema&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;azurescout.assessment-answers/v1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;answers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ruleId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CASA-TR-01&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;answer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Yes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;note&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Documented in the cloud policy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>A plain object keyed by rule ID also works: <code>{ &quot;CASA-TR-01&quot;: &quot;Yes&quot;, &quot;CASA-TR-02&quot;: { &quot;answer&quot;: &quot;No&quot;, &quot;note&quot;: &quot;...&quot; } }</code>.</p>`,18)])])}const k=e(i,[["render",o]]);export{u as __pageData,k as default};
